// Opening hours for the curated list come from Google (npm run places:hours); editorial hours text wins when present.
const googleHours = curatedHours as Record<string, { hours?: string; periods?: [number, number][] }>;
export const places: Place[] = curated.map((place) => {
  const found = googleHours[place.id];
  return found ? { ...place, hours: place.hours ?? found.hours, openingPeriods: found.periods } : place;
});
